insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_102_v1'
from (values
('127.759.d.1.A',3,'A student charts how a Texas trial court, a court of appeals and a high court fit together beside the federal district, circuit and Supreme Court layers. This traces the:','["structure and function of state and federal court systems", "structure of a hospital", "structure of a bank", "structure of a school district"]'::jsonb,0,'Both systems have layered courts.','original'),
('127.759.d.1.A',4,'The U.S. Supreme Court''s main role is to:','["hold every trial", "hear final appeals and interpret the Constitution", "write all statutes", "enforce arrests"]'::jsonb,1,'It is the highest federal court.','original'),
('127.759.d.1.B',3,'A chart shows that a speeding ticket in Austin goes to a municipal court while a bank robbery across state lines can go to federal district court. This compares:','["two grocery chains", "two bus routes", "the state court system and the federal court system", "two school districts"]'::jsonb,2,'Each system hears different cases.','original'),
('127.759.d.1.B',4,'A case about a violation of a federal statute is typically heard in:','["a school board", "a city park", "a county fair", "a federal court"]'::jsonb,3,'Federal law is enforced in federal court.','original'),
('127.759.d.1.C',3,'A crime committed in one county but involving a victim in another raises the question of which court may hear it. This illustrates how:','["jurisdiction affects charges and trial procedure", "weather affects trials", "music affects trials", "fashion affects trials"]'::jsonb,0,'Jurisdiction decides authority.','original'),
('127.759.d.1.C',4,'A court''s jurisdiction is its:','["building size", "legal authority to hear a case", "docket color", "number of seats"]'::jsonb,1,'Jurisdiction = power to decide.','original'),
('127.759.d.1.D',3,'A criminal statute exists to deter harmful acts, punish offenders and protect the public. These are the:','["rules for board games", "rules for recipes", "purposes of law regarding criminal acts and behaviors", "rules for sports uniforms"]'::jsonb,2,'Law aims to protect society.','original'),
('127.759.d.1.D',4,'One purpose of criminal law is to:','["hide offenses", "encourage crime", "avoid punishment", "deter conduct that harms others"]'::jsonb,3,'Deterrence is a goal.','original'),
('127.759.d.1.E',3,'A student sorts sources: the Fourth Amendment, a Supreme Court decision, a state penal code and an agency regulation. This distinguishes:','["constitutional, case, statutory and administrative law", "food groups", "car brands", "music genres"]'::jsonb,0,'Four sources of law.','original'),
('127.759.d.1.E',4,'A law passed by a legislature is called:','["common sense", "statutory law", "administrative law", "case law"]'::jsonb,1,'Statutes come from legislatures.','original'),
('127.759.d.1.F',3,'A shoplifting charge for a small item moves differently through the system than an armed robbery. This identifies differences in processing a:','["permit and a license", "lawsuit and a contract", "misdemeanor and a felony", "ticket and a map"]'::jsonb,2,'Felonies are more serious.','original'),
('127.759.d.1.F',4,'Compared with misdemeanors, felony cases generally involve:','["no courts", "no lawyers", "less evidence needed", "more serious punishments and more formal procedures"]'::jsonb,3,'Felonies carry greater penalties.','original'),
('127.759.d.1.G',3,'A panel of citizens reviews a prosecutor''s evidence to decide whether there is enough to indict. This describes the impact of the:','["grand jury process", "trial jury verdict", "sentencing", "bail hearing"]'::jsonb,0,'A grand jury decides on indictment.','original'),
('127.759.d.1.G',4,'A grand jury''s primary job is to decide whether:','["a defendant is guilty", "there is probable cause to charge someone", "a judge should retire", "a sentence is fair"]'::jsonb,1,'Indictments need probable cause.','original'),
('127.759.d.1.H',3,'A student connects the Fourth, Fifth and Sixth Amendments to rights in a trial. This examines the relationship of the:','["school handbook to lunch menus", "map to roads", "U.S. Constitution and the Bill of Rights to the court system", "poem to rhyme"]'::jsonb,2,'The Bill of Rights guides procedure.','original'),
('127.759.d.1.H',4,'The first ten amendments to the Constitution are known as the:','["Preamble", "Articles", "Federalist Papers", "Bill of Rights"]'::jsonb,3,'The Bill of Rights.','original'),
('127.759.d.1.I',3,'After a major public outcry about a crime, legislators propose tougher sentences. This describes the impact of:','["public opinion and the legislature on the court system", "hobbies on grades", "sports on diets", "weather on traffic"]'::jsonb,0,'Opinion shapes law.','original'),
('127.759.d.1.I',4,'Public opinion can influence courts indirectly by:','["writing opinions", "affecting the laws legislators pass", "removing judges daily", "choosing verdicts directly"]'::jsonb,1,'Legislatures respond to voters.','original'),
('127.759.d.2.A',3,'In a hearing, an officer testifies, a prosecutor presents the case, a judge rules and a victim describes the harm. This explains the roles of:','["pilots and crew", "chefs and waiters", "police, prosecutor, judge and victim in the court process", "coaches and players"]'::jsonb,2,'Each actor has a defined role.','original'),
('127.759.d.2.A',4,'The prosecutor''s role in a criminal case is to:','["defend the accused", "write the law", "decide the verdict alone", "represent the government in presenting the case"]'::jsonb,3,'The prosecutor represents the state.','original'),
('127.759.d.2.B',3,'During a trial, a bailiff keeps order, a clerk records filings and jurors weigh the facts. This examines the roles of:','["courtroom members such as the jury and bailiff", "lifeguards", "stage crew", "cafeteria staff"]'::jsonb,0,'Courtroom staff keep the process orderly.','original'),
('127.759.d.2.B',4,'The jury''s main function in a criminal trial is to:','["arrest defendants", "decide the facts and reach a verdict", "write sentences into law", "interpret the Constitution"]'::jsonb,1,'Juries find facts.','original'),
('127.759.d.2.C',3,'A victim impact statement and a defendant''s testimony both shape how a case proceeds. This analyzes the impact of:','["the lighting on a case", "the weather on a case", "the victim and the defendant on the courtroom process", "the carpet on a case"]'::jsonb,2,'Both parties affect proceedings.','original'),
('127.759.d.2.C',4,'A victim impact statement is typically presented:','["during jury selection", "before arrest", "at the grand jury only", "at sentencing"]'::jsonb,3,'It informs the sentencing decision.','original'),
('127.759.d.2.D',3,'A busy court moves dozens of plea cases through in one morning, and officials use discretion on what to pursue. This discusses:','["assembly line justice and discretion in court processes", "random justice", "slow justice only", "no justice"]'::jsonb,0,'Heavy caseloads create assembly-line dynamics.','original'),
('127.759.d.2.D',4,'Prosecutorial discretion means the prosecutor may:','["pick the judge", "decide whether and how to bring charges", "hire jurors", "write the verdict"]'::jsonb,1,'Prosecutors choose charges.','original'),
('127.759.d.3.A',3,'A trainee notes that a witness avoids eye contact, speaks quietly and fidgets. This evaluates:','["food flavors", "weather patterns", "body language such as gestures and tone", "tire wear"]'::jsonb,2,'Nonverbal cues carry meaning.','original'),
('127.759.d.3.A',4,'When reading body language, an observer should remember that:','["a gesture always proves guilt", "silence means nothing", "tone never matters", "cues are clues and need context"]'::jsonb,3,'Context matters.','original'),
('127.759.d.3.B',3,'A court clerk speaks clearly, listens and confirms details back to a nervous citizen. This demonstrates:','["interpersonal communication skills", "silence", "avoidance", "interrupting"]'::jsonb,0,'Clear communication builds trust.','original'),
('127.759.d.3.B',4,'Active listening in the courtroom setting includes:','["checking a phone", "paraphrasing to confirm understanding", "ignoring speakers", "talking over others"]'::jsonb,1,'Confirming prevents misunderstanding.','original'),
('127.759.d.3.C',3,'An officer writes a clear, factual note on times, names and actions that later becomes an accurate report. This applies:','["poetry skills", "art skills", "writing skills for field notes and report writing", "dance skills"]'::jsonb,2,'Good notes make good reports.','original'),
('127.759.d.3.C',4,'An effective court-related report should be:','["vague", "disorganized", "opinionated", "clear, factual and organized"]'::jsonb,3,'Reports must be reliable.','original'),
('127.759.d.4.A',3,'An officer brings a case to a prosecutor, who decides what complaint to file and how to work with the court. This examines the interaction of:','["police and prosecutor in filing complaints", "chef and waiter", "coach and player", "teacher and student"]'::jsonb,0,'Prosecutors review police cases.','original'),
('127.759.d.4.A',4,'A prosecutor may decline to file a complaint if:','["it is a holiday", "the evidence is insufficient", "the weather is bad", "the officer is tired"]'::jsonb,1,'Evidence drives charging decisions.','original'),
('127.759.d.4.B',3,'Before trial, lawyers exchange evidence and argue to exclude certain items. This explains pretrial proceedings such as:','["cake baking", "car racing", "rules of discovery and challenges to evidence", "chess clubs"]'::jsonb,2,'Discovery shares evidence.','original'),
('127.759.d.4.B',4,'The rules of discovery require parties to:','["hide evidence", "destroy evidence", "wait until the verdict", "share certain evidence before trial"]'::jsonb,3,'Discovery promotes fairness.','original'),
('127.759.d.4.C',3,'A fingerprint on a weapon is direct proof of contact, while a suspect''s distance from a scene suggests but does not prove presence. This distinguishes:','["direct and circumstantial evidence", "new and old evidence", "loud and quiet evidence", "red and blue evidence"]'::jsonb,0,'Circumstantial evidence implies.','original'),
('127.759.d.4.C',4,'In a criminal trial the prosecution must prove guilt:','["by majority opinion", "beyond a reasonable doubt", "by a coin toss", "by probability only"]'::jsonb,1,'Burden of proof is high.','original'),
('127.759.d.4.D',3,'A defendant agrees to plead guilty to a lesser charge in exchange for a lighter sentence. This explores:','["parole boards", "trial by combat", "pleas and plea bargaining", "jury picking"]'::jsonb,2,'Pleas resolve most cases.','original'),
('127.759.d.4.D',4,'A plea bargain generally results in:','["a longer trial", "an automatic appeal", "no sentence ever", "a resolution without a full trial"]'::jsonb,3,'Plea deals avoid trials.','original'),
('127.759.d.4.E',3,'A chart lists arraignment, jury selection, opening statements, evidence, closings, verdict and sentencing. This identifies the:','["trial process from pretrial to sentencing", "school calendar", "lunch menu", "bus schedule"]'::jsonb,0,'Trial steps follow a sequence.','original'),
('127.759.d.4.E',4,'Which step comes immediately before closing arguments?','["sentencing", "presentation of evidence", "jury selection", "arraignment"]'::jsonb,1,'Evidence precedes closings.','original'),
('127.759.d.4.F',3,'Students review a fictional case file, weigh evidence and decide what charges apply. This evaluates:','["a fashion show", "a cooking contest", "a simulated criminal case", "a soccer match"]'::jsonb,2,'Simulations teach case analysis.','original'),
('127.759.d.4.F',4,'In a case simulation, strong analysis relies on:','["guesses", "rumors", "favorites", "facts, law and logical reasoning"]'::jsonb,3,'Reason from evidence.','original'),
('127.759.d.4.G',3,'Students play judge, jurors, attorneys and witnesses in a courtroom exercise with real procedure. This is a:','["mock trial of the criminal trial procedure", "dance recital", "science fair", "book sale"]'::jsonb,0,'Mock trials teach process.','original'),
('127.759.d.4.G',4,'In a mock trial, an attorney''s opening statement:','["gives the verdict", "outlines what the evidence will show", "argues the law only", "gives the sentence"]'::jsonb,1,'Openings preview the case.','original'),
('127.759.d.5.A',3,'An officer must have a reasonable basis before searching a car, honoring the amendment that protects against unreasonable searches. This applies the:','["Second Amendment", "First Amendment", "Fourth Amendment responsibilities of police", "Third Amendment"]'::jsonb,2,'The Fourth Amendment regulates searches.','original'),
('127.759.d.5.A',4,'A deputy wants to open a locked backpack with no warrant and no emergency. Which constitutional protection limits this?','["the Twelfth Amendment rules on electors", "the Second Amendment right to bear arms", "the Third Amendment ban on quartering soldiers", "the Fourth Amendment ban on unreasonable searches"]'::jsonb,3,'Searches generally need a warrant or an exception.','original'),
('127.759.d.5.B',3,'A trainee reviews a scenario where an officer enters a home without a warrant and decides if it fits an exception. This determines if the search was:','["proper under constitutional provisions", "fast", "quiet", "popular"]'::jsonb,0,'Compare facts to exceptions.','original'),
('127.759.d.5.B',4,'A search warrant is usually required unless:','["the officer is in uniform", "an exception such as exigent circumstances applies", "the home is large", "it is a weekday"]'::jsonb,1,'Exceptions are narrow.','original'),
('127.759.d.5.C',3,'Evidence found through an illegal stop is thrown out, along with additional evidence found because of it. This analyzes the exclusionary rule and:','["the jury duty rule", "the speedy trial rule", "the fruit of the poisonous tree doctrine", "the double jeopardy clause"]'::jsonb,2,'Derivative evidence is also excluded.','original'),
('127.759.d.5.C',4,'Under the fruit of the poisonous tree doctrine, evidence derived from an illegal search is generally:','["automatically strong", "always admissible", "required", "inadmissible"]'::jsonb,3,'Taint spreads to derivative evidence.','original'),
('127.759.d.5.D',3,'A court rules that an extremely harsh punishment is unconstitutional. This explains the impact of the:','["Eighth, Ninth and Tenth Amendments", "Seventh and Twelfth Amendments", "First and Second Amendments", "Third and Fourth Amendments"]'::jsonb,0,'The Eighth bars cruel and unusual punishment.','original'),
('127.759.d.5.D',4,'The Eighth Amendment prohibits:','["gun ownership", "cruel and unusual punishment and excessive bail", "free speech", "religious worship"]'::jsonb,1,'Eighth = punishment limits.','original'),
('127.759.d.5.E',3,'Cases such as Miranda v. Arizona, Weeks v. United States and Gideon v. Wainwright reshaped police and court practice. This analyzes the effect of:','["sports finals", "pop songs", "landmark court cases", "recent movies"]'::jsonb,2,'Landmark decisions set precedent.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_102_v1'
from (values
('127.759.d.5.E',4,'Gideon v. Wainwright established the right to:','["a free vehicle", "a jury of animals", "remain silent forever", "an attorney for those who cannot afford one"]'::jsonb,3,'Gideon: counsel for the poor.','original'),
('127.759.d.5.F',3,'A defendant receives notice, a fair hearing and an impartial decision-maker at trial and sentencing. These describe:','["due process rights of a criminal suspect", "parking rights", "travel rights", "voting rights"]'::jsonb,0,'Due process ensures fairness.','original'),
('127.759.d.5.F',4,'Due process generally guarantees a defendant:','["an automatic acquittal", "a fair procedure before being deprived of liberty", "freedom from all arrest", "a pardon"]'::jsonb,1,'Fair process is the guarantee.','original'),
('127.759.d.5.G',3,'A defendant cannot be forced to testify against themself and has the right to a speedy public trial with a lawyer. This explains the impact of the:','["Seventh and Eighth", "Ninth and Tenth", "Fifth and Sixth Amendments", "First and Third"]'::jsonb,2,'Fifth and Sixth protect defendants.','original'),
('127.759.d.5.G',4,'The Fifth Amendment protects against:','["quartering soldiers", "censorship", "unreasonable taxes", "self-incrimination"]'::jsonb,3,'No compelled self-incrimination.','original'),
('127.760.d.12',3,'A security trainee studies how to break away from a hold and safely control a threat using approved methods. This analyzes procedures and protocols for:','["self-defense in homeland security", "menu planning", "poetry", "gardening"]'::jsonb,0,'Protocols guide safe defense.','original'),
('127.760.d.12',4,'Self-defense procedures in security work should be used:','["as punishment", "only as authorized and with minimum necessary force", "for fun", "whenever possible"]'::jsonb,1,'Force must be justified and limited.','original'),
('127.760.d.1.A',3,'A new hire arrives early, dresses to policy, speaks respectfully and follows instructions. This demonstrates:','["carelessness", "rule breaking", "positive work behaviors and professional standards", "tardiness"]'::jsonb,2,'Professionalism shows reliability.','original'),
('127.760.d.1.A',4,'Which behavior reflects professional standards in a security job?','["sleeping on duty", "gossiping", "ignoring rules", "punctuality and respectful conduct"]'::jsonb,3,'Professional habits matter.','original'),
('127.760.d.1.B',3,'In a simulation, an officer finds a coworker pocketing a small item and decides to report it. This applies:','["ethical reasoning to simulation situations", "peer pressure", "denial", "avoidance"]'::jsonb,0,'Ethics guide choices.','original'),
('127.760.d.1.B',4,'Ethical reasoning in security work involves choosing actions that are:','["easy", "honest and fair", "profitable only", "hidden"]'::jsonb,1,'Integrity first.','original'),
('127.760.d.1.C',3,'Three recruits split tasks to secure a venue and check in with one another by radio. This demonstrates:','["isolation", "rivalry", "teamwork skills", "avoidance"]'::jsonb,2,'Teams share goals.','original'),
('127.760.d.1.C',4,'A team member can best support the group by:','["working alone", "blaming others", "hiding mistakes", "communicating clearly and sharing responsibility"]'::jsonb,3,'Cooperation improves results.','original'),
('127.760.d.1.D',3,'An officer treats people of different backgrounds with respect and keeps private information private. This shows value for:','["diversity and confidentiality", "gossip", "stereotypes", "secrets sharing"]'::jsonb,0,'Respect and discretion.','original'),
('127.760.d.1.D',4,'Confidentiality in security work means:','["telling coworkers everything", "protecting sensitive information from unauthorized people", "trading stories", "posting online"]'::jsonb,1,'Keep sensitive info private.','original'),
('127.760.d.1.E',3,'A trainee accurately uses terms like ''perimeter,'' ''access control'' and ''incident report'' while working a drill. This demonstrates:','["slang only", "jokes", "understanding of technical vocabulary on the job", "guessing"]'::jsonb,2,'Vocabulary supports clarity.','original'),
('127.760.d.1.E',4,'Using correct technical vocabulary helps by:','["hiding meaning", "slowing response", "confusing others", "reducing misunderstandings among team members"]'::jsonb,3,'Clear terms matter.','original'),
('127.760.d.2.A',3,'A timeline shows how agencies like the FBI, Secret Service and Border Patrol began and expanded. This researches the development of:','["federal law enforcement and protective services", "film studios", "local garden clubs", "school sports"]'::jsonb,0,'Federal agencies grew over time.','original'),
('127.760.d.2.A',4,'The U.S. Secret Service is best known for:','["growing crops", "protecting national leaders and investigating financial crimes", "operating hospitals", "running schools"]'::jsonb,1,'Protection and finance crimes.','original'),
('127.760.d.2.B',3,'A federal agent works with city police and state investigators on a trafficking case. This explains the importance of the:','["separation of duties only", "rivalry among agencies", "interface between federal, state and local agencies", "secret work alone"]'::jsonb,2,'Cooperation improves results.','original'),
('127.760.d.2.B',4,'Cooperation between federal and local agencies helps to:','["duplicate every task", "delay cases", "hide evidence", "share intelligence and resources"]'::jsonb,3,'Shared info speeds work.','original'),
('127.760.d.3.A',3,'A trainee points out wet floors, exposed wires and unlabeled chemicals as risks to people and the environment. This identifies:','["workplace hazards", "benefits", "hobbies", "decorations"]'::jsonb,0,'Hazards threaten health and safety.','original'),
('127.760.d.3.A',4,'A tripping hazard in a hallway is a hazard to:','["the budget only", "worker safety", "the schedule only", "the weather"]'::jsonb,1,'Trip hazards injure people.','original'),
('127.760.d.3.B',3,'A supervisor walks through a facility with a checklist to find unsafe equipment and ventilation problems. This is a:','["menu tasting", "fashion review", "workplace inspection", "party planning"]'::jsonb,2,'Inspections find problems.','original'),
('127.760.d.3.B',4,'The goal of a safety inspection is to:','["decorate the site", "delay work", "assign blame", "find and correct hazards before harm occurs"]'::jsonb,3,'Prevention.','original'),
('127.760.d.3.C',3,'After a simulated accident, a trainee writes down time, witnesses, conditions and photos. This investigates and documents:','["workplace incidents and accidents", "a holiday", "a ball game", "a school play"]'::jsonb,0,'Documentation supports corrective action.','original'),
('127.760.d.3.C',4,'An incident report should be:','["edited later", "factual and complete", "vague", "opinionated"]'::jsonb,1,'Accuracy matters.','original'),
('127.760.d.3.D',3,'A trainee reads a safety sheet describing risks of storing flammable and toxic chemicals. This summarizes problems associated with:','["office furniture", "computer games", "hazardous materials", "sports gear"]'::jsonb,2,'Hazmat requires special care.','original'),
('127.760.d.3.D',4,'A guard finds a leaking drum clearly labeled with a chemical''s name and wants to know how to handle it safely. Which document lists its hazards and handling steps?','["the shift schedule", "the visitor sign-in log", "the employee handbook cover", "the Safety Data Sheet"]'::jsonb,3,'SDS lists chemical hazards and handling.','original'),
('127.760.d.4.A',3,'One case involves a neighbor suing over a fence line, while another involves the state prosecuting a theft. This differentiates:','["civil law and criminal law", "art and design", "music and dance", "food and drink"]'::jsonb,0,'Civil resolves disputes; criminal punishes offenses.','original'),
('127.760.d.4.A',4,'Criminal cases are brought by:','["a company only", "the government", "a private neighbor", "a club"]'::jsonb,1,'Government prosecutes crimes.','original'),
('127.760.d.4.B',3,'A trainee studies how arrest powers, use of force and privacy laws limit federal officers. This analyzes:','["recipes", "game rules", "legal issues relevant to federal law enforcement and protective services", "fashion trends"]'::jsonb,2,'Law limits authority.','original'),
('127.760.d.4.B',4,'An officer''s authority to use force is limited by:','["public opinion alone", "the officer''s mood", "personal preference", "law and agency policy"]'::jsonb,3,'Authority is bounded.','original'),
('127.760.d.4.C',3,'A guard greets visitors politely, explains rules calmly and thanks them. This describes the importance of:','["good public relations in federal and security work", "secrecy", "indifference", "rudeness"]'::jsonb,0,'Courtesy builds trust.','original'),
('127.760.d.4.C',4,'Good public relations in security work can:','["increase confrontations", "improve cooperation and reduce conflict", "lower safety", "hide duties"]'::jsonb,1,'Respect eases tensions.','original'),
('127.760.d.4.D',3,'A student traces how the Constitution, federal statutes and agency rules guide what federal officers may do. This analyzes the connection between:','["map scales and roads", "song lyrics and tempo", "constitutional and federal laws and law enforcement", "school rules and lunch"]'::jsonb,2,'Higher law governs enforcement.','original'),
('127.760.d.4.D',4,'Which has the highest legal authority in the United States?','["a company policy", "a city memo", "a club bylaw", "the U.S. Constitution"]'::jsonb,3,'Supremacy of the Constitution.','original'),
('127.760.d.4.E',3,'A security manager reviews state licensing rules, a local ordinance and a federal statute that all apply to a government building. This analyzes:','["specific federal, state and local laws affecting government facilities", "fashion laws", "menu laws", "sports laws"]'::jsonb,0,'Multiple laws overlap.','original'),
('127.760.d.4.E',4,'When federal, state and local rules differ, security staff should:','["pick the easiest", "follow the applicable and most restrictive requirements", "guess", "ignore them"]'::jsonb,1,'Comply with all applicable rules.','original'),
('127.760.d.4.F',3,'A guard learns that detaining a minor involves special rules about notification and rights. This summarizes:','["import laws", "tax laws", "juvenile laws affecting security operations", "zoning laws"]'::jsonb,2,'Juvenile rules differ.','original'),
('127.760.d.4.F',4,'When dealing with a juvenile, security staff should:','["ignore rules", "treat them as adults", "release them anywhere", "follow special legal requirements and notify proper authorities"]'::jsonb,3,'Special rules protect minors.','original'),
('127.760.d.4.G',3,'In a role-play, one trainee uses calm words while another uses unnecessary force, and the group compares outcomes. This compares:','["alternative responses in simulated security scenarios", "routes", "recipes", "playlists"]'::jsonb,0,'Compare consequences.','original'),
('127.760.d.4.G',4,'A good response in a security scenario is one that is:','["most forceful", "lawful, proportionate and effective", "loudest", "fastest"]'::jsonb,1,'Proportionality guides action.','original'),
('127.760.d.4.H',3,'An officer who accepts bribes or abuses authority may lose their job and face prosecution. This discusses:','["bonuses", "promotions", "ramifications of unethical behavior by security personnel", "vacations"]'::jsonb,2,'Unethical acts have consequences.','original'),
('127.760.d.4.H',4,'A possible consequence of unethical conduct by a security officer is:','["a medal", "less supervision", "a raise", "discipline, firing or criminal charges"]'::jsonb,3,'Accountability follows misconduct.','original'),
('127.760.d.4.I',3,'A guard checks whether searching a visitor''s bag is reasonable and authorized under the amendment protecting against unreasonable searches. This analyzes the:','["Fourth Amendment as it applies to security officers", "Third Amendment only", "Second Amendment only", "First Amendment only"]'::jsonb,0,'Searches must be reasonable.','original'),
('127.760.d.4.I',4,'The Fourth Amendment generally applies most directly to:','["vehicles only", "government actors such as police", "pets", "private homes only"]'::jsonb,1,'Constraints on government.','original'),
('127.760.d.4.J',3,'A government officer must provide fair procedures before taking someone''s liberty. This summarizes the due process granted by the:','["Ninth Amendment", "Third Amendment", "Fifth Amendment", "Seventh Amendment"]'::jsonb,2,'Fifth includes due process.','original'),
('127.760.d.4.J',4,'Under the Fifth Amendment, no person may be:','["made to pay tax", "required to vote", "forced to travel", "compelled to testify against themself"]'::jsonb,3,'Self-incrimination protection.','original'),
('127.760.d.4.K',3,'A court applies equal protection and due process to state actions under the amendment ratified after the Civil War. This analyzes the impact of the:','["Fourteenth Amendment", "First Amendment", "Twenty-First Amendment", "Eighth Amendment"]'::jsonb,0,'The Fourteenth applies to states.','original'),
('127.760.d.4.K',4,'The Fourteenth Amendment requires states to provide:','["a free vehicle", "due process and equal protection of the laws", "free food", "free housing"]'::jsonb,1,'Core guarantees.','original'),
('127.760.d.4.L',3,'A viral post about an incident affects public trust and interferes with an investigation. This analyzes the importance and effects of:','["weather", "traffic", "social media on federal law enforcement and security", "architecture"]'::jsonb,2,'Online posts shape perception and cases.','original'),
('127.760.d.4.L',4,'An officer should be careful about posting case details online because it could:','["speed court", "improve secrecy", "reduce attention", "compromise an investigation and violate policy"]'::jsonb,3,'Sharing sensitive info is risky.','original'),
('127.760.d.5.A',3,'A planner lists floods, sabotage and an accidental chemical leak as sources of risk to a facility. This describes:','["natural, intentional and unintentional threats", "game genres", "school subjects", "fashion trends"]'::jsonb,0,'Threats vary in origin.','original'),
('127.760.d.5.A',4,'An example of an intentional threat is:','["a storm", "sabotage", "a power flicker", "a spill by accident"]'::jsonb,1,'Sabotage is deliberate.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_102_v1'
from (values
('127.760.d.5.B',3,'A security team shows how a broken fence, a weak password and a stolen badge each create weaknesses. This presents examples of:','["music notes", "art colors", "physical, electronic, procedural and personnel vulnerabilities", "sports plays"]'::jsonb,2,'Vulnerabilities arise in many areas.','original'),
('127.760.d.5.B',4,'A weak password is an example of a:','["natural hazard", "physical hazard only", "legal rule", "electronic vulnerability"]'::jsonb,3,'Cyber weakness.','original'),
('127.760.d.5.C',3,'A planner identifies risks, ranks them and chooses controls at city, state and national levels. This summarizes:','["the concept of risk management", "a travel itinerary", "a menu plan", "a sports strategy"]'::jsonb,0,'Risk management is a process.','original'),
('127.760.d.5.C',4,'Risk management typically involves:','["waiting", "assessing risks and selecting measures to reduce them", "adding more risk", "ignoring them"]'::jsonb,1,'Assess then control.','original'),
('127.760.d.5.D',3,'A private security firm shares tips with police, and prosecutors rely on its reports. This explains how security operations and the criminal justice field:','["compete only", "ignore each other", "interface and relate to one another", "operate alone"]'::jsonb,2,'They support each other.','original'),
('127.760.d.5.D',4,'Private security often supports criminal justice by:','["handling trials", "making arrests only", "writing laws", "reporting incidents and preserving evidence"]'::jsonb,3,'They provide info and protect scenes.','original'),
('127.760.d.6.A',3,'Analysts use software to recover deleted files and trace logins in an investigation. This summarizes the role of:','["computer applications in forensic investigations", "word games", "board games", "video games"]'::jsonb,0,'Software aids forensics.','original'),
('127.760.d.6.A',4,'A forensic tool that can recover deleted files helps investigators:','["avoid cases", "find digital evidence", "delete more files", "hide activity"]'::jsonb,1,'Recovery uncovers evidence.','original'),
('127.760.d.6.B',3,'A task force traces a phishing scam across the Internet and across borders. This investigates criminal activity in areas such as:','["art classes", "street parades", "cybercrime and Internet crimes", "farm work"]'::jsonb,2,'Cybercrime uses networks.','original'),
('127.760.d.6.B',4,'Phishing is a cybercrime in which attackers:','["print documents", "deliver mail", "fix computers", "trick people into revealing sensitive information"]'::jsonb,3,'Phishing deceives users.','original'),
('127.760.d.7.A',3,'A guard sees keycards, locks, cameras and alarms controlling who enters a building. This summarizes types and applications of:','["physical and electronic access control systems", "menu boards", "furniture", "signage"]'::jsonb,0,'Access control manages entry.','original'),
('127.760.d.7.A',4,'A keycard reader is an example of an:','["fire hydrant", "electronic access control device", "parking stripe", "trash can"]'::jsonb,1,'Electronic access device.','original'),
('127.760.d.7.B',3,'Fences, cameras and software logs all feed into one security plan. This analyzes how physical and electronic systems work as an:','["single lock", "unrelated parts", "integrated security system", "random mix"]'::jsonb,2,'Layers work together.','original'),
('127.760.d.7.B',4,'Integrating alarms with cameras improves security because it:','["hides events", "removes the need for staff", "ignores threats", "lets staff verify alarms quickly"]'::jsonb,3,'Verification speeds response.','original'),
('127.760.d.7.C',3,'A team walks the site, tests alarms and runs a drill to see if responses work. This analyzes the role of:','["security surveys, inspections and exercises", "contests", "parties", "advertisements"]'::jsonb,0,'Testing reveals gaps.','original'),
('127.760.d.7.C',4,'The purpose of a security exercise is to:','["avoid reports", "test existing measures and find weaknesses", "scare staff", "replace policies"]'::jsonb,1,'Exercises evaluate readiness.','original'),
('127.760.d.8.A',3,'A training slide lists violence or threats against civilians to intimidate and advance a political aim. This summarizes the characteristics of:','["a festival", "a prank", "terrorism as a criminal act", "a sport"]'::jsonb,2,'Terrorism is criminal violence for intimidation.','original'),
('127.760.d.8.A',4,'A defining feature of terrorism is that it aims to:','["sell goods", "raise funds", "entertain", "intimidate or coerce a population or government"]'::jsonb,3,'Intimidation for a goal.','original'),
('127.760.d.8.B',3,'Planners secure power grids, water systems and communication networks so a single attack cannot cripple a region. This examines:','["critical infrastructure protection", "rentals", "decor", "coupons"]'::jsonb,0,'Protect essential systems.','original'),
('127.760.d.8.B',4,'Critical infrastructure includes:','["clothing", "power, water and communication systems", "toys", "video games"]'::jsonb,1,'Essential services.','original'),
('127.760.d.9.A',3,'Analysts plan, collect, process, analyze and share information in a repeating loop. This summarizes the steps of the:','["bicycle cycle", "life cycle", "intelligence cycle", "water cycle"]'::jsonb,2,'The intelligence cycle.','original'),
('127.760.d.9.A',4,'In the intelligence cycle, analysis comes after:','["feedback", "planning only", "dissemination", "collection and processing of information"]'::jsonb,3,'Analysis follows processing.','original'),
('127.760.d.9.B',3,'An analyst plots burglaries on a map and notices they cluster near a closed factory. This executes a:','["crime pattern analysis", "sports ranking", "recipe test", "music chart"]'::jsonb,0,'Mapping reveals links.','original'),
('127.760.d.9.B',4,'Crime pattern analysis helps agencies:','["reduce staff", "predict and prevent related crimes", "hide patterns", "avoid data"]'::jsonb,1,'Patterns inform strategy.','original'),
('127.760.d.10.A',3,'A student draws a triangle with ability, opportunity and motive and explains that removing one side prevents the crime. This diagrams the:','["pyramid scheme", "golden ratio", "crime triangle", "triangle offense"]'::jsonb,2,'All three are needed.','original'),
('127.760.d.10.A',4,'Removing which element of the crime triangle makes a crime less likely?','["breakfast", "lighting only", "music", "opportunity"]'::jsonb,3,'Reduce opportunity.','original'),
('127.760.d.10.B',3,'A security plan uses signs to discourage, sensors to notice, barriers to slow and guards to stop intruders. This describes:','["deter, detect, delay and deny", "run, jump, climb and hide", "buy, sell, hold and trade", "read, write, add and draw"]'::jsonb,0,'Four security layers.','original'),
('127.760.d.10.B',4,'Cameras that notify a guard of movement mainly serve to:','["delay only", "detect", "deny only", "deter only"]'::jsonb,1,'Detection alerts staff.','original'),
('127.760.d.10.C',3,'A security expert recommends better lighting, trimmed shrubs and clear sightlines for a store. This evaluates security using:','["web design", "fashion design", "crime prevention through environmental design", "game design"]'::jsonb,2,'CPTED reduces opportunity.','original'),
('127.760.d.10.C',4,'Natural surveillance in crime prevention means:','["avoiding lights", "hiding entrances", "blocking windows", "designing spaces so people can easily observe activity"]'::jsonb,3,'Visibility discourages crime.','original'),
('127.760.d.11.A',3,'In a drill, trainees move from verbal commands to restraint only as the subject''s resistance escalates. This demonstrates the:','["force continuum", "shift rotation", "fitness test", "lunch rotation"]'::jsonb,0,'Force matches resistance.','original'),
('127.760.d.11.A',4,'The force continuum helps officers choose a response that is:','["random", "proportionate to the subject''s behavior", "always minimum", "always maximum"]'::jsonb,1,'Proportionality.','original'),
('127.760.d.11.B',3,'An instructor reviews state and federal rules that limit how and when force may be used. This explains:','["menu rules", "game rules", "guidelines and restrictions on use of force", "parking rules"]'::jsonb,2,'Law limits force.','original'),
('127.760.d.11.B',4,'Excessive force by an officer can lead to:','["praise", "extra tools", "promotions", "civil liability and criminal charges"]'::jsonb,3,'Accountability.','original'),
('127.760.d.13.A',3,'A federal planner explains why ports, dams and pipelines are vital to the nation. This discusses the importance of:','["critical infrastructure and key assets", "decorations", "toys", "souvenirs"]'::jsonb,0,'They are essential to public welfare.','original'),
('127.760.d.13.A',4,'A key asset such as a dam is important because its loss could:','["help the budget", "harm public safety or the economy", "have no effect", "improve safety"]'::jsonb,1,'Failure cascades.','original'),
('127.760.d.13.B',3,'City and state officials write steps to evacuate, coordinate and recover if a power plant is threatened. This creates a:','["party plan", "travel plan", "plan of action for threats to critical infrastructure", "menu plan"]'::jsonb,2,'Planning improves response.','original'),
('127.760.d.13.B',4,'An action plan for a threat should include:','["only slogans", "only photos", "only music", "roles, communication and response steps"]'::jsonb,3,'Plans assign roles and steps.','original'),
('127.760.d.14.A',3,'Students read research on airborne particles and toxic exposures and their health impact. This analyzes research on:','["the cause and effects of chemical threats", "gaming tips", "shoe trends", "cooking fads"]'::jsonb,0,'Chemical threats harm health.','original'),
('127.760.d.14.A',4,'Airborne chemical agents are especially dangerous because they:','["stay in place", "spread quickly and can be inhaled", "are always odorless", "are always visible"]'::jsonb,1,'Inhalation risk.','original'),
('127.760.d.14.B',3,'A class designs a project about how a chemical release affects air quality and health in a city. This creates:','["a party", "a poem", "a research project on chemical threats", "a game"]'::jsonb,2,'Research projects deepen understanding.','original'),
('127.760.d.14.B',4,'A strong research project on chemical threats should cite:','["social posts only", "hearsay", "rumors", "reliable scientific and government sources"]'::jsonb,3,'Reliable sources.','original'),
('127.760.d.15.A',3,'A family writes a plan for a home emergency with routes, contacts and a kit. This develops a plan for:','["disaster preparedness within home, school or community", "a vacation", "a party", "a sale"]'::jsonb,0,'Preparedness plan.','original'),
('127.760.d.15.A',4,'A disaster plan should be reviewed and practiced:','["only once", "regularly", "after the disaster", "never"]'::jsonb,1,'Practice keeps it ready.','original'),
('127.760.d.15.B',3,'A class checks whether warning sirens, shelters and evacuation routes actually work for floods and tornadoes. This evaluates:','["a movie", "a school lunch", "the effectiveness of actions in place for natural disasters", "a ball game"]'::jsonb,2,'Evaluation improves plans.','original'),
('127.760.d.15.B',4,'The effectiveness of a shelter plan can be tested by:','["ignoring it", "waiting for a disaster", "skipping the plan", "conducting a drill and noting problems"]'::jsonb,3,'Drills reveal gaps.','original'),
('127.760.d.15.C',3,'After a drill, leaders review whether alerts, rescue and recovery steps worked. This evaluates:','["preparedness and response systems during and after disasters", "bake sales", "awards shows", "fashion shows"]'::jsonb,0,'After-action reviews.','original'),
('127.760.d.15.C',4,'An after-action review is meant to:','["assign blame only", "identify what worked and what needs improvement", "end the plan", "hide results"]'::jsonb,1,'Learn and improve.','original'),
('127.760.d.15.D',3,'A team looks at a damaged building, injured people and limited resources to decide what to do first. This appraises a disaster to determine:','["no action", "a random action", "the appropriate course of action", "a fast exit"]'::jsonb,2,'Assess and prioritize.','original'),
